import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"配置数据点历史存储","description":"按项目、来源和单点设置历史策略，核对触发、目标、保留期，并与报警历史及备份分开。","frontmatter":{"title":"配置数据点历史存储","description":"按项目、来源和单点设置历史策略，核对触发、目标、保留期，并与报警历史及备份分开。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/point-history.md","filePath":"zh/使用指南/配置数据点历史存储.md"}'),d={name:"zh/guide/point-history.md"};function i(h,t,n,s,p,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="配置数据点历史存储" tabindex="-1">配置数据点历史存储 <a class="header-anchor" href="#配置数据点历史存储" aria-label="Permalink to &quot;配置数据点历史存储&quot;">​</a></h1><p>历史存储用于记录数据点样本，方便后续查询和趋势分析。它不同于当前值、报警历史、工程导出或服务器备份。</p><p>入口：<strong>数据中心 → 历史存储</strong>。单点也可从“数据点”的“历史存储”进入。先取得配置权限，确认数据来源与可用存储目标。</p><h2 id="_1-先看哪一层生效" tabindex="-1">1. 先看哪一层生效 <a class="header-anchor" href="#_1-先看哪一层生效" aria-label="Permalink to &quot;1. 先看哪一层生效&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>用途</th></tr></thead><tbody><tr><td>项目默认策略</td><td>未单独设置的来源跟随它，新来源默认继承</td></tr><tr><td>来源策略</td><td>对某个接入源或采集连接安排历史方式</td></tr><tr><td>单点例外</td><td>数据点可沿用来源，或按该点单独设置</td></tr></tbody></table><p>先检查继承关系，再修改。关闭来源历史后，已有单点例外仍可能继续保存，按页面提醒核对，不能只看来源状态推断所有点。</p><h2 id="_2-选择保存方式和触发" tabindex="-1">2. 选择保存方式和触发 <a class="header-anchor" href="#_2-选择保存方式和触发" aria-label="Permalink to &quot;2. 选择保存方式和触发&quot;">​</a></h2><p>打开目标设置，选择沿用上层、不保存历史或 <strong>“按策略保存”</strong>。需要自定时，可先选一项合适的“预设”，再核对具体字段。</p><p>记录触发可按每个样本、间隔或值变化安排。最短写入间隔、变化死区、最长间隔等选项会影响数据量与记录效果，不是都越小越好。</p><p>“不保存历史”停止新增记录，不等于删除已有历史。历史策略也不会自动把一个按需 SQL 查询变成持续采集器；没有实际样本来源时，不会凭空产生运行历史。</p><h2 id="_3-核对存储目标和保留期" tabindex="-1">3. 核对存储目标和保留期 <a class="header-anchor" href="#_3-核对存储目标和保留期" aria-label="Permalink to &quot;3. 核对存储目标和保留期&quot;">​</a></h2><p>选择可用的主存储目标，按业务保留期填写。需要附加目标时，确认容量与相应权限。</p><p>多个目标各自收到一份数据，<strong>不是主备自动切换</strong>；保留期也分别设置。不要把多存一份当成完整备份或灾备方案。</p><p>断线时可按策略保留最后值并标为异常，或不记录。检查报表和趋势如何识别这些质量信息，不把旧值误当作新的正常采样。</p><h2 id="_4-保存后还要更新运行内容" tabindex="-1">4. 保存后还要更新运行内容 <a class="header-anchor" href="#_4-保存后还要更新运行内容" aria-label="Permalink to &quot;4. 保存后还要更新运行内容&quot;">​</a></h2><p>点击 <strong>“保存”</strong>，重新打开核对最终设置。批量配置前核对选择范围与例外，不误覆盖大量来源。</p><p>这些设置保存在工程中，需要发布、更新并激活相应运行内容后才在节点生效。保存成功不能证明历史服务已经开始写入。</p><p>正式验证时，核对部署版本、存储服务、输入样本、时间范围和质量，再检查确有新记录产生。不要用开发态默认值展示的曲线证明现场历史完整。</p><h2 id="出现问题时" tabindex="-1">出现问题时 <a class="header-anchor" href="#出现问题时" aria-label="Permalink to &quot;出现问题时&quot;">​</a></h2><p>先查来源有没有新样本，再查继承关系、保存触发、运行部署、存储目标和保留期。涉及清理或重建存储服务时先安排备份，不为修复趋势图直接删除库。</p><p>下一步：<a href="/induframe-docs/zh/guide/data-flow-tutorial.html">计算与报警联动</a> · <a href="/induframe-docs/zh/guide/operations-records.html">运维记录</a>。</p>',21)])])}const u=a(d,[["render",i]]);export{c as __pageData,u as default};
